#!/usr/bin/env bash
set -euo pipefail

app=/home/eval/app
old_version=$(cat "$app/VERSION")
IFS=. read -r major minor patch <<< "$old_version"

bump=$(awk '
    /^BREAKING/ || /^[[:alnum:]_-]+!:/ { breaking = 1 }
    /^feat:/ { feature = 1 }
    END {
        if (breaking) print "major"
        else if (feature) print "minor"
        else print "patch"
    }
' "$app/changes.txt")

major=$((10#$major))
minor=$((10#$minor))
patch=$((10#$patch))

case "$bump" in
    major) major=$((major + 1)); minor=0; patch=0 ;;
    minor) minor=$((minor + 1)); patch=0 ;;
    patch) patch=$((patch + 1)) ;;
esac
new_version="$major.$minor.$patch"

tmp=$(mktemp "$app/.changelog.XXXXXX")
trap 'rm -f "$tmp"' EXIT

awk -v version="$new_version" -v changes="$app/changes.txt" '
    {
        print
        if ($0 == "## Unreleased" && !inserted) {
            inserted = 1
            print ""
            print "## " version " (2026-10-09)"
            while ((getline change < changes) > 0) {
                if (change ~ /^(feat|fix)!?:/)
                    print "- " change
            }
            close(changes)
        }
    }
' "$app/CHANGELOG.md" > "$tmp"

mv "$tmp" "$app/CHANGELOG.md"
printf '%s\n' "$new_version" > "$app/VERSION"
printf '%s -> %s\n' "$old_version" "$new_version"
exit 0
